SELECT a.request_id AS request_id, a.user_id AS user_id, u.username AS username, u.display_name AS display_name, a.question AS question, a.sql AS sql, a.summary AS summary, a.confidence AS confidence, a.rows_returned AS row_count, a.execution_time_ms AS execution_ms, a.status AS status, a.recommended_chart AS recommended_chart, a.created_at AS created_at, a.org_id AS org_id, o.org_name AS org_name, a.is_favorite AS is_favorite, a.retry_count AS retry_count, a.feedback AS feedback FROM audit_query_logs a LEFT JOIN dim_org o ON a.org_id = o.id LEFT JOIN sys_user u ON a.user_id = u.id
AND a.user_id = #{userId}
AND a.org_id IN
#{orgId}
AND (u.username ILIKE '%' || #{username} || '%' OR u.display_name ILIKE '%' || #{username} || '%')
AND a.question ILIKE '%' || #{keyword} || '%' AND a.created_at >= #{startDate} AND a.created_at < #{endDate} AND a.confidence >= #{minConfidence} AND a.confidence <= #{maxConfidence}
ORDER BY a.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM audit_query_logs a
LEFT JOIN sys_user u ON a.user_id = u.id

    AND a.user_id = #{userId}

        AND a.org_id IN

            #{orgId}



        AND (u.username ILIKE '%' || #{username} || '%' OR u.display_name ILIKE '%' || #{username} || '%')

    AND a.question ILIKE '%' || #{keyword} || '%'
    AND a.created_at >= #{startDate}
    AND a.created_at < #{endDate}
    AND a.confidence >= #{minConfidence}
    AND a.confidence <= #{maxConfidence}

SELECT a.request_id AS request_id, a.user_id AS user_id, a.org_id AS org_id, o.org_name AS org_name, a.question AS question, a.sql AS generated_sql, a.prompt_context AS prompt_context, a.status AS status, a.execution_time_ms AS execution_ms, a.rows_returned AS row_count, a.confidence AS confidence, a.retry_count AS retry_count, a.cache_hit AS cache_hit, a.feedback_rating AS feedback_rating, a.created_at AS created_at, a.error_message AS error_message FROM audit_query_logs a LEFT JOIN dim_org o ON a.org_id = o.id
AND a.user_id = #{userId} AND a.org_id = #{orgId}
AND a.org_id IN
#{allowedOrgId}
AND a.status IN ('error', 'blocked') AND a.status = 'success' AND COALESCE(a.confidence, 0) < 0.7 AND a.status = #{status}
AND a.created_at >= #{startDate} AND a.created_at < #{endDate} AND a.confidence >= #{minConfidence} AND a.confidence <= #{maxConfidence}
ORDER BY a.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM audit_query_logs a

    AND a.user_id = #{userId}
    AND a.org_id = #{orgId}

        AND a.org_id IN

            #{allowedOrgId}




            AND a.status IN ('error', 'blocked')
            AND a.status = 'success' AND COALESCE(a.confidence, 0) < 0.7
            AND a.status = #{status}


    AND a.created_at >= #{startDate}
    AND a.created_at < #{endDate}
    AND a.confidence >= #{minConfidence}
    AND a.confidence <= #{maxConfidence}

SELECT a.request_id AS request_id, a.user_id AS user_id, a.org_id AS org_id, o.org_name AS org_name, a.question AS question, a.sql AS generated_sql, a.prompt_context AS prompt_context, a.status AS status, a.execution_time_ms AS execution_ms, a.rows_returned AS row_count, a.confidence AS confidence, a.retry_count AS retry_count, a.cache_hit AS cache_hit, a.feedback_rating AS feedback_rating, a.created_at AS created_at, a.error_message AS error_message FROM audit_query_logs a LEFT JOIN dim_org o ON a.org_id = o.id WHERE a.request_id = #{requestId}
AND a.org_id IN
#{allowedOrgId}

SELECT COUNT(*) AS total_queries, COUNT(*) FILTER (WHERE status = 'success') AS success_count, COUNT(*) FILTER (WHERE status <> 'success') AS failed_count, COALESCE(ROUND(AVG(execution_time_ms)), 0) AS avg_execution_ms, COALESCE(AVG(confidence), 0) AS avg_confidence, COUNT(*) FILTER (WHERE cache_hit = true) AS cache_hit_count FROM audit_query_logs
created_at >= #{startDate}
AND org_id IN
#{allowedOrgId}

SELECT user_id AS user_id, COUNT(*) AS count FROM audit_query_logs
created_at >= #{startDate} AND user_id IS NOT NULL
AND org_id IN
#{allowedOrgId}
GROUP BY user_id ORDER BY count DESC, user_id ASC LIMIT #{limit}

SELECT DATE(created_at) AS date, COUNT(*) AS count, COALESCE(ROUND(AVG(execution_time_ms)), 0) AS avg_ms FROM audit_query_logs
created_at >= #{startDate}
AND org_id IN
#{allowedOrgId}
GROUP BY DATE(created_at) ORDER BY DATE(created_at) ASC
